<?php require __DIR__.'/../includes/bootstrap.php';require_member();$pageTitle='My library dashboard';$basePath='../';$s=$pdo->prepare('SELECT * FROM members WHERE user_id=?');$s->execute([current_user()['id']]);$member=$s->fetch();if(!$member)exit('Member profile not found. Contact the library administrator.');$s=$pdo->prepare('SELECT l.*,b.title,b.author FROM loans l JOIN books b ON b.id=l.book_id WHERE l.member_id=? ORDER BY l.id DESC');$s->execute([$member['id']]);$loans=$s->fetchAll();$borrowed=0;$overdue=0;$estimate=0;foreach($loans as $l){if($l['status']==='issued'){$borrowed+=(int)$l['quantity'];$days=overdue_days($l['due_date']);if($days>0){$overdue++;$estimate+=$days*(float)setting($pdo,'fine_per_day',10);}}}$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM fines WHERE member_id=? AND status="unpaid"');$s->execute([$member['id']]);$recorded=(float)$s->fetchColumn();$fine=$recorded+$estimate;$recent=array_slice($loans,0,6);require __DIR__.'/../includes/layout_top.php';?><div class="welcome member-welcome"><div><span class="eyebrow light">YOUR LIBRARY ACCOUNT</span><h2>Welcome, <?=e($member['name'])?></h2><p>See your borrowed books, due dates and fine information.</p></div><div class="welcome-icon">♙</div></div><div class="stats-grid"><div class="stat"><span>Currently borrowed</span><b><?=$borrowed?></b><small>Books in your account</small></div><div class="stat"><span>Borrowing records</span><b><?=count($loans)?></b><small>Past and current loans</small></div><div class="stat"><span>Overdue records</span><b class="text-danger"><?=$overdue?></b><small>Require return</small></div><div class="stat"><span>Unpaid fine + estimate</span><b><?=money($fine)?></b><small>Final amount confirmed on return</small></div></div><div class="panel"><div class="panel-head"><div><h3>My borrowed books</h3><p>Books issued to you by the library administrator.</p></div><a class="btn small" href="loans.php">View all</a></div><div class="table-wrap"><table><thead><tr><th>Book</th><th>Issue date</th><th>Due date</th><th>Quantity</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $l):?><tr><td><b><?=e($l['title'])?></b><small><?=e($l['author'])?></small></td><td><?=e($l['issue_date'])?></td><td><?=e($l['due_date'])?></td><td><?=$l['quantity']?></td><td><span class="pill <?=$l['status']==='issued'?'warning':'success'?>"><?=$l['status']?></span></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="5" class="empty">No books have been issued to your account. Please contact the library administrator.</td></tr><?php endif;?></tbody></table></div></div><div class="notice">Book issue, return and fine payment are controlled by the library administrator. You can view your own records here.</div><?php require __DIR__.'/../includes/layout_bottom.php';?>
